function F.harvest(fd)
    S.task = __T["Harvesting field "] .. fd.n
    local before = F.cropBag()
    local list = fd.crops:GetChildren()
    table.sort(list, function(a, b)
        local pa, pb = a:IsA("BasePart") and a.Position or a:GetPivot().Position, b:IsA("BasePart") and b.Position or b:GetPivot().Position
        if math.abs(pa.X - pb.X) > 1 then return pa.X < pb.X end
        return pa.Z < pb.Z
    end)
    local cap = M.basketCap()
    for i, c in ipairs(list) do
        if not RUNNING or not on("f_crops") or on("f_pause") then break end
        if c.Parent then
            local pos = c:IsA("BasePart") and c.Position or c:GetPivot().Position
            M.tp(CFrame.new(pos.X, pos.Y + 2.5, pos.Z))
            task.wait(0.07)
        end
        if i % 10 == 0 then M.state(true) if M.basket() >= cap then break end end
    end
    task.wait(0.3)
    M.state(true)
    local got = F.cropBag() - before
    if got <= 0 then
        F.back["h" .. fd.n] = os.clock() + 20
        F.planted[fd.n] = { at = os.clock() - F.growTime(fd) + 15, crop = F.planted[fd.n] and F.planted[fd.n].crop }
    elseif #fd.crops:GetChildren() == 0 then
        F.planted[fd.n] = nil
    end
    return got > 0
end
function F.crops()
    local fields = F.fields()
    if #fields == 0 then return false end
    if M.basket() >= M.basketCap() - 2 and F.cropBag() > 0 then return F.sell() end
    for _, fd in ipairs(fields) do
        if fd.count == 0 and fd.crops and F.plant(fd) then return true end
    end
    if M.basket() < M.basketCap() - 5 then
        for _, fd in ipairs(fields) do
            if F.ripe(fd) then F.harvest(fd) return true end
        end
    end
    if F.cropBag() > 0 then return F.sell() end
    return false
end
F.oreIds = { stone = true }
