        local fc = D.MN.FACES[face.Name]
        if fc then
            for _, b in ipairs(face:GetChildren()) do
                local x, y, z = b.Name:match("^B(%d+)_(%d+)_(%d+)$")
                if x and b:IsA("BasePart") and F.due("blk" .. face.Name .. b.Name) then out[#out + 1] = { b = b, face = face.Name, fc = fc, x = tonumber(x), y = tonumber(y), z = tonumber(z) } end
