function F.mine()
    if not (M.owned("MineShaft") and D.MN) then return false end
    local ev = rem("MineAim")
    if not ev then return false end
    local room = M.basketCap() - M.basket()
    if F.oreBag() > 0 and room < 3 then return F.mineSell() end
    if room < 3 then return false end
    local list = F.blocks()
    if #list == 0 then return F.mineSell() end
    local r = M.hrp()
    local here = r and r.Position or Vector3.zero
    table.sort(list, function(a, b)
        if a.y ~= b.y then return a.y < b.y end
        return (a.b.Position - here).Magnitude < (b.b.Position - here).Magnitude
    end)
    S.task = __T["Mining"]
    M.unseat()
    local t0 = os.clock()
    for i = 1, math.min(10, #list) do
        local e = list[i]
        if not (RUNNING and on("f_mine") and not on("f_pause") and M.alive()) or os.clock() - t0 > 12 or M.basketCap() - M.basket() < 2 then break end
        if e.b.Parent then
            local out = e.fc.out and Vector3.new(e.fc.out.X, 0, e.fc.out.Y) or Vector3.new(0, 0, 1)
            local idx = D.MN.index(e.fc, e.x, e.y, e.z)
            local stand = e.b.Position + out * 6
            local bt = os.clock()
            M.hold(CFrame.lookAt(stand, e.b.Position))
            while e.b.Parent and os.clock() - bt < 4 and on("f_mine") and not on("f_pause") and M.alive() do
                pcall(ev.FireServer, ev, e.face, idx)
                task.wait(0.25)
            end
            pcall(ev.FireServer, ev, nil)
            if e.b.Parent then F.back["blk" .. e.face .. e.b.Name] = os.clock() + 60 else S.blocks = (S.blocks or 0) + 1 end
            M.state()
        end
    end
    M.release()
    if F.oreBag() >= 20 then F.mineSell() end
    return true
end
