    local best = B.bestCrop(s)
    if not best then return end
    local sel = s.selected
    if sel ~= best then
        local have = M.num(s.seeds and s.seeds[best])
        if have >= fields or M.num(D.CR[best].seedPrice) * fields <= B.spend() or M.num(s.seeds and sel and s.seeds[sel]) <= 0 then
            if B.try("sel", "selectSeed", best) then s.selected = best sel = best end
        end
    end
    if not sel then return end
    local want = math.max(2, fields * 2)
    local have = M.num(s.seeds and s.seeds[sel])
    if have >= want then return end
    local price = M.num(D.CR[sel] and D.CR[sel].seedPrice)
