    Menu:AddToggle("ui_toasts", { Text = __T["Hide Game Popups"], Default = false, Tooltip = __T["Hides the game's toast spam"] })
    local function toasts(hide)
        local pg = lp:FindFirstChildOfClass("PlayerGui")
