    task.spawn(function() while RUNNING do if on("ui_toasts") then pcall(toasts, true) end task.wait(1) end end)
    Toggles.ui_toasts:OnChanged(function(v) if not v then pcall(toasts, false) end end)
    onClean(function() pcall(toasts, false) end)
    Menu:AddButton({ Text = __T["Unload"], Func = function() pcall(_G.__CW_RAF_CLEAN) end })
    SaveManager:SetLibrary(Library)
    ThemeManager:SetLibrary(Library)
    SaveManager:IgnoreThemeSettings()
    SaveManager:SetIgnoreIndexes({ "MenuKeybind", "FeedbackType", "FeedbackMsg", "f_pause", "r_code" })
    ThemeManager:SetFolder("COMBO_WICK_RAF")
    SaveManager:SetFolder("COMBO_WICK_RAF")
    ThemeManager:ApplyToTab(Tab)
    pcall(function()
        if not (isfile and isfile("COMBO_WICK_RAF/themes/default.txt")) then ThemeManager:ApplyTheme("Tokyo Night") end
    end)
    SaveManager:BuildConfigSection(Tab)
end)
task.spawn(function()
    while RUNNING do
        pcall(function()
            local mins = math.max((os.clock() - S.t0) / 60, 0.25)
            local s = M.state() or {}
            local st = F.stand()
            setText(UI.s1, string.format(__T["Cash $%s · +$%s/min · %dm"], M.short(M.cash()), M.short(S.earned / mins), math.floor(mins)))
            setText(UI.s2, __T["Doing: "] .. S.task)
            setText(UI.s3, string.format(__T["Basket %d/%d · Stand %s/%s"], M.basket(), M.basketCap(), st and M.num(st:GetAttribute("Used")) or "-", st and M.num(st:GetAttribute("Cap")) or "-"))
            setText(UI.s4, string.format(__T["Eggs %s · Crops %s · Ore %s"], M.short(S.eggs), M.short(S.crops), M.short(S.ore or 0)))
            setText(UI.s5, string.format(__T["Pads %d · Hens %d · Workers %d"], S.pads, S.hens, S.workers))
            local fields = #F.fields()
            setText(UI.s6, string.format(__T["Fields %d · Seed %s x%d"], fields, tostring(s.selected or "-"), M.num(s.seeds and s.selected and s.seeds[s.selected])))
            setText(UI.es, string.format(__T["Collected %d · Fish %d"], S.estate or 0, S.fish or 0))
            local w = s.weighoff
            if w then
                local wet = M.num(w.wetUntil) - Workspace:GetServerTimeNow()
                setText(UI.pk, w.open and string.format(__T["%s lb · fed %s/%s today · %s"], M.short(w.lb), M.short(w.fedToday), M.short((D.WO and D.WO.DAILY_LB) or 1500), wet > 0 and (__T["wet "] .. math.floor(wet / 60) .. "m") or __T["dry"]) or __T["Pumpkin patch is locked"])
            end
            local i = 0
            for _, q in pairs(s.quests or {}) do
                if type(q) == "table" and i < 3 then i = i + 1 setText(UI["q" .. i], string.format(__T["Quest: %s %s/%s → $%s"], tostring(q.kind), M.short(q.have), M.short(q.goal), M.short(q.reward))) end
            end
            for j = i + 1, 3 do setText(UI["q" .. j], "") end
        end)
        task.wait(0.5)
    end
end)
onClean(function() pcall(function() Library:Unload() end) end)
pcall(function()
    local name, ok, err = SaveManager:GetAutoloadConfig()
    local loaded = false
    if ok and not err then
        loaded = SaveManager:Load(name) == true
        if not loaded then SaveManager.Library:Notify("Autoload config not found, using last settings") end
    end
    if not loaded and isfile and isfile("COMBO_WICK_RAF/settings/auto.json") then SaveManager:Load("auto") end
end)
do
    local pending = false
    local function queue()
        if pending or not RUNNING then return end
        pending = true
        task.delay(1.5, function() pending = false; if RUNNING then pcall(function() if not SaveManager.Library.Unloaded then SaveManager:Save("auto") end end) end end)
    end
    local function skip(k) k = tostring(k); return k == "f_pause" or k == "MenuKeybind" or k == "r_code" or k:find("^ThemeManager") or k:find("^SaveManager") or k:find("Color") or k == "FeedbackMsg" or k == "FeedbackType" end
    task.delay(2, function()
        for k, t in pairs(Toggles) do if not skip(k) then pcall(function() local prev = t.Changed t:OnChanged(function(...) if prev then pcall(prev, ...) end queue() end) end) end end
        for k, o in pairs(Opt) do if not skip(k) then pcall(function() local prev = o.Changed o:OnChanged(function(...) if prev then pcall(prev, ...) end queue() end) end) end end
    end)
end
function UI.center()
    pcall(function()
        local sg = Library.ScreenGui
        local m = sg and sg:FindFirstChild("Main")
        if not m then return end
        m.AnchorPoint = Vector2.zero
        for _ = 1, 3 do
            local vs, sz, cur = sg.AbsoluteSize, m.AbsoluteSize, m.AbsolutePosition
            local tx, ty = math.max(0, math.floor((vs.X - sz.X) / 2)), math.max(0, math.floor((vs.Y - sz.Y) / 2))
            local k = (m.Size.X.Offset > 0 and sz.X / m.Size.X.Offset) or 1
            if math.abs(cur.X - tx) < 2 and math.abs(cur.Y - ty) < 2 then break end
            m.Position = UDim2.new(m.Position.X.Scale, m.Position.X.Offset + (tx - cur.X) / k, m.Position.Y.Scale, m.Position.Y.Offset + (ty - cur.Y) / k)
            RunService.Heartbeat:Wait()
        end
    end)
end
for _, dl in ipairs({ 1, 3, 6 }) do task.delay(dl, UI.center) end
function UI.fixSize()
    pcall(function()
        local m = Library.ScreenGui and Library.ScreenGui:FindFirstChild("Main")
        local cam = Workspace.CurrentCamera
        if not (m and cam) then return end
        local vs = cam.ViewportSize
        if vs.X >= 300 and vs.Y >= 250 and (m.AbsoluteSize.X < 250 or m.AbsoluteSize.Y < 200) then
            m.Size = UDim2.fromOffset(math.min(580, vs.X - 20), math.min(480, vs.Y - 20))
            task.defer(UI.center)
        end
    end)
end
task.spawn(function() while RUNNING do UI.fixSize() task.wait(1) end end)
task.spawn(function()
    local miss = {}
    for _, n in ipairs(getgenv().CW_NEEDS or {}) do if not CAP.cap(n) then miss[#miss + 1] = n end end
    if #miss > 0 then
        setText(UI.exec, '<font color="#ff6b6b">' .. __T["Missing on your executor: "] .. table.concat(miss, ", ") .. __T[". Auto planting is off."] .. '</font>')
    elseif not D.BT then
        setText(UI.exec, '<font color="#ff6b6b">' .. __T["Your executor can't read game data. Some features are limited."] .. '</font>')
    else
        setText(UI.exec, '<font color="#7ED957">' .. __T["Executor check: all features supported"] .. '</font>')
    end
    LOG("exec check", "missing=" .. table.concat(miss, ","))
end)
notify(__T["Loaded"])

end
